<script setup lang="ts">import {ref,computed} from 'vue';import {Plus,Camera,FileText,MapPin,ChevronDown,BadgeCheck} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import {useSelectedVehicle} from '../composables/useSelectedVehicle';import {useVintro} from '../composables/useVintro';const {vehicle,base}=useSelectedVehicle();const {state}=useVintro();const filter=ref('All');const open=ref('');const types=['All','Service','Repair','Tyre change','Inspection','Mileage update','Document upload','Accident / body repair','Modification','Ownership transfer','Workshop recommendation'];const events=computed(()=>state.vehicleEvents.filter(e=>e.vehicleId===vehicle.value.id&&(filter.value==='All'||e.type===filter.value)))
</script>
<template><PageHeader title="Vehicle timeline" :back="base"><RouterLink :to="`${base}/add-event`" class="btn-secondary !min-h-10"><Plus :size="16"/>Add event</RouterLink></PageHeader><div class="container-app max-w-4xl py-7"><p class="eyebrow">{{vehicle.make}} {{vehicle.model}}</p><h1 class="page-title mt-2">The complete story</h1><p class="mt-3 text-muted">Every recorded event across ownership, maintenance and documentation.</p><div class="-mx-5 mt-7 overflow-x-auto px-5"><div class="flex min-w-max gap-2"><button v-for="type in types" @click="filter=type" class="rounded-full border px-4 py-2 text-sm font-medium" :class="filter===type?'border-ink bg-ink text-white':'bg-white'">{{type}}</button></div></div><div class="mt-8"><article v-for="event in events" :key="event.id" class="relative pb-7 pl-8 last:pb-0 before:absolute before:left-[7px] before:top-4 before:h-full before:w-px before:bg-line last:before:hidden"><span class="absolute left-0 top-1.5 h-[15px] w-[15px] rounded-full border-4 border-canvas bg-accent"/><button @click="open=open===event.id?'':event.id" class="card w-full p-5 text-left hover:shadow-soft"><div class="flex items-start justify-between gap-3"><div><p class="nums text-xs text-muted">{{event.date}} · {{event.mileage.toLocaleString()}} km · {{event.type}}</p><h2 class="mt-1.5 text-lg font-semibold">{{event.title}}</h2></div><ChevronDown :size="18" class="shrink-0 transition" :class="{'rotate-180':open===event.id}"/></div><p class="mt-3 text-sm leading-6 text-muted">{{event.description}}</p><div class="mt-4 flex flex-wrap gap-3 text-xs text-muted"><span v-if="event.workshop" class="flex items-center gap-1"><MapPin :size="13"/>{{event.workshop}}</span><span v-if="event.photos" class="flex items-center gap-1"><Camera :size="13"/>{{event.photos}} photos</span><span v-if="event.documents" class="flex items-center gap-1"><FileText :size="13"/>{{event.documents}} documents</span><span class="flex items-center gap-1" :class="event.verification==='Workshop verified'?'text-success':''"><BadgeCheck :size="13"/>{{event.verification}}</span></div><div v-if="open===event.id" class="mt-5 border-t pt-4"><div v-if="event.parts.length"><p class="text-xs text-muted">Parts used</p><p class="mt-1 text-sm">{{event.parts.join(' · ')}}</p></div><div class="mt-4 flex justify-between text-sm"><span class="text-muted">Cost</span><strong v-if="event.cost" class="nums">{{event.currency}} {{event.cost}}</strong><span v-else>Not recorded</span></div><p v-if="event.notes" class="mt-4 rounded-xl bg-stone-50 p-3 text-sm text-muted">{{event.notes}}</p></div></button></article><div v-if="!events.length" class="rounded-2xl border border-dashed p-10 text-center text-muted">No events in this category.</div></div></div></template>
